import { useRef, useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios'

import home from '../css/home.module.css'
import logsignForm from '../css/sub/logsignForm.module.css'
import getBase from '../js/getBase.js'
import openAlert from '../js/alert-box.js'

import TSLlogo from '../assets/img/TSLlogo.png';

export default function HomePage() {
    const navigate = useNavigate();
    getBase()

    const [name_f, setName] = useState('')
    const [email_f, setEmail] = useState('')
    const [authToken, setAuthToken] = useState(localStorage.getItem('authToken'));
    const [isAdmin, setIsAdmin] = useState('');
    const didRun = useRef(false);
    const projects = [
        {
            title: "Title",
            desc: "description",
            img: "https://placehold.co/600x350?text=Image",
        }, {
            title: "Title",
            desc: "description",
            img: "https://placehold.co/600x350?text=Image",
        }, {
            title: "Title",
            desc: "description",
            img: "https://placehold.co/600x350?text=Image",
        }, {
            title: "Title",
            desc: "description",
            img: "https://placehold.co/600x350?text=Image",
        }, {
            title: "Title",
            desc: "description",
            img: "https://placehold.co/600x350?text=Image",
        }, {
            title: "Title",
            desc: "description",
            img: "https://placehold.co/600x350?text=Image",
        }
    ];

    async function checkState() {
        await axios.post('/checkAdminServer', {token: authToken})
            .then(res => {
                setIsAdmin(res.data)
                return
            }).catch(err => {
                setIsAdmin(false)
                return
            })
    }
    checkState()

    useEffect(() => {
        if (didRun.current) return;
        didRun.current = true;
        
        if (!authToken && isTokenExpired()) {
            refreshToken();
        }
        else if (authToken && !isTokenExpired() && isAdmin) {
            navigate('/admin')
            return
        }
        else if (authToken && !isTokenExpired()) {
            navigate('/learn')
            return
        }


        import('../js/app-home.js')
        const grid = document.getElementById("project_grid");
        projects.forEach((p) => {
            const card = document.createElement("article");
            card.className = `${home.project_card} ${home.fade}`;
            card.innerHTML = `
                <img src="${p.img}" alt="${p.title}">
                <div class="${home.content}">
                <h4>${p.title}</h4>
                <p>${p.desc}</p>
                </div>
            `;
            grid.appendChild(card);
        });

        const mainForm = document.querySelector('#chkFormSec');
        const log_h = document.querySelector('.login .handler');
        const sign_h = document.querySelector('.signup .handler');
        const timing = 30;
        const formTxt = {
            sign: {
                main: 'Sign up',
                change: "Don't have an account?"
            },
            log: {
                main: 'Login',
                change: "Already a user?"
            }
        };

        let change_main, change_sub;

        mainForm.addEventListener('click', () => {
            clearInterval(change_main);
            clearInterval(change_sub);

            let chgt_m = '';
            let chgt_s = '';
            let count_m = 0;
            let count_s = 0;

            const isLogin = mainForm.checked;
            const mainText = isLogin ? formTxt.sign.change : formTxt.log.change;
            const subText = isLogin ? formTxt.log.main : formTxt.sign.main;
            const mainHandler = isLogin ? sign_h : log_h;
            const subHandler = isLogin ? log_h : sign_h;

            if (isLogin) {
                document.querySelector('.signinBtnGroup').inert = true
                document.querySelector('.loginBtnGroup').inert = false
            } else {
                document.querySelector('.signinBtnGroup').inert = false
                document.querySelector('.loginBtnGroup').inert = true
            }

            change_main = setInterval(() => {
                if (count_m === mainText.length) {
                    clearInterval(change_main);
                } else {
                    chgt_m += mainText[count_m];
                    mainHandler.innerHTML = chgt_m;
                    count_m += 1;
                }
            }, timing);

            change_sub = setInterval(() => {
                if (count_s === subText.length) {
                    clearInterval(change_sub);
                } else {
                    chgt_s += subText[count_s];
                    subHandler.innerHTML = chgt_s;
                    count_s += 1;
                }
            }, timing * 4);
        });


        const logsignMainForm = document.querySelector(`.${logsignForm.mainForm}`)
        const formChk = document.querySelector('#chkFormSec')
        const overlay = document.querySelector('#overlay-setting-container')
        const mainClick = document.querySelector('#loginClick')

        mainClick.addEventListener('click', () => {
            logsignMainForm.style.display = 'block'
            overlay.style.display = 'block'
            setTimeout(() => {
                logsignMainForm.style.opacity = '1'
                overlay.style.opacity = '1'
            }, 1);
        })
        overlay.addEventListener('click', () => {
            if (formChk.checked) {
                formChk.click()
            }

            logsignMainForm.style.opacity = '0'
            overlay.style.opacity = '0'
            setTimeout(() => {
                logsignMainForm.style.display = 'none'
                overlay.style.display = 'none'
            }, 250);
        })
    }, [authToken, isAdmin]);



    async function signup(data) {
        const name = name_f;
        const email = email_f;
        const pswd = data.get("pswd");
        const name_e = document.querySelector(`.${logsignForm.signup} .${logsignForm.inputform}.${logsignForm.name}`);
        const email_e = document.querySelector(`.${logsignForm.signup} .${logsignForm.inputform}.${logsignForm.email}`);
        
        await axios.post('/signinServer', {name, email, pswd})
        .then(res => {
                if (res.data.theme !== 'success') {
                    name_e.value = name
                    email_e.value = email
                }
                openAlert(res.data.theme, res.data.title, res.data.content)
            })
            .catch(err => {
                console.error(err)
                openAlert('danger', 'Error', "Unable to signup via API")
            })
    }

    async function login(data) {
        const email = email_f;
        const pswd = data.get("pswd");
        const email_e = document.querySelector(`.${logsignForm.login} .${logsignForm.inputform}.${logsignForm.email}`);

        await axios.post('/loginServer', {email, pswd})
        .then(res => {
            openAlert(res.data.theme, res.data.title, res.data.content) 
            if (res.data.theme != 'success') {
                email_e.value = email
            }
            if (res.data.theme == 'success') {
                const accessToken = res.data.token
                const user_data = res.data.user_data
                localStorage.setItem('authToken', accessToken)
                localStorage.setItem('name', user_data.name)
                localStorage.setItem('email', user_data.email)
                localStorage.setItem('profile', user_data.profile)
                setAuthToken(accessToken)
            }
        })
        .catch(err => {
            console.error(err)
            openAlert('danger', 'Error', "Unable to login via API")
        })
    }

    async function refreshToken() {
        await axios.post('/tokenServer')
            .then(res => {
                const accessToken = res.data.token
                localStorage.setItem('authToken', accessToken)
                setAuthToken(accessToken)
                console.log(accessToken);
            })
            .catch(err => {
                console.error('Error refreshing token:', err);
            })
    };

    const isTokenExpired = () => {
        const token = localStorage.getItem('authToken');

        if (!token) return true;
        if (token.split('.').length !== 3) {
            console.error('Invalid token format');
            return true;
        }
        
        try {
            const decodedToken = JSON.parse(atob(token.split('.')[1]));
            return decodedToken.exp < Date.now() / 1000;
        } catch (e) {
            console.error('Error decoding token:', e);
            return true;
        }
    };



    return (
        <>
        <header id='header'>
            <div className={home.container}>
                <img className={home.logo} src={TSLlogo} style={{width: 'calc(4.2em)'}}/>
                <nav>
                    <ul>
                        <li><a href="#home">Home</a></li>
                        <li><a href="#about">About</a></li>
                        <li><a href="#content">Content</a></li>
                    </ul>
                    <button id='burger'><i className="fa fa-bars"></i></button>
                </nav>
            </div>
        </header>
        <div className={logsignForm.mainForm}>
            <input type="checkbox" id='chkFormSec' aria-hidden="true" className={logsignForm.inputform} />
            <div className={logsignForm.signup}>
                <form action={signup}>
                    <label htmlFor="chkFormSec" aria-hidden="true" className={logsignForm.handler}>Sign up</label>
                    <div className={`${logsignForm.logsignSend} ${logsignForm.signinBtnGroup}`}>
                        <input type="text" name="name" placeholder="name" required className={`${logsignForm.inputform} ${logsignForm.name}`} onChange={e => setName(e.target.value)}/>
                        <input type="email" name="email" placeholder="email" required className={`${logsignForm.inputform} ${logsignForm.email}`} onChange={e => setEmail(e.target.value)}/>
                        <input type="password" name="pswd" placeholder="password" minLength={8} required className={logsignForm.inputform} />
                        <button id='btnFormSign' className={logsignForm.btnform}>Sign up</button>
                    </div>
                </form>
            </div>
            <div className={logsignForm.login}>
                <form action={login}>
                    <label htmlFor="chkFormSec" aria-hidden="true" className={logsignForm.handler}>Already a user?</label>
                    <div className={`${logsignForm.logsignSend} ${logsignForm.loginBtnGroup}`} inert>
                        <input type="email" name="email" placeholder="email" required className={`${logsignForm.inputform} ${logsignForm.email}`} onChange={e => setEmail(e.target.value)}/>
                        <input type="password" name="pswd" placeholder="password" required className={logsignForm.inputform} />
                        <button id='btnFormLog' className={logsignForm.btnform}>Login</button>
                    </div>
                </form>
            </div>
        </div>
        <section id='home' className={home.hero}>
            <div className={home.container}>
                <h2>Welcome to <span className={home.accent}>ThSL learn place</span></h2>
                <p>A fun, free and awesome way to learn languages!</p>
                <div className={home.social}>
                    <i className="ph ph-hand-palm"></i>
                    <i className="ph ph-hand-peace"></i>
                    <i className="ph ph-hand-pointing"></i>
                    <i className="ph ph-hand-waving"></i>
                    <i className="ph ph-hands-praying"></i>
                    <i className="ph ph-hand-grabbing"></i>
                </div>
                <a className={home.btn} id='loginClick'>Let's Start</a>
            </div>
        </section>
        <div className={home.sectionAbout} id="about">
            <section className={`${home.section} ${home.aboutSec}`}>
                <div className={`${home.container} ${home.grid_2}`}>
                    <img className={home.image} src="https://placehold.co/500x500" alt="Profile"/>
                    <div className={home.text}>
                        <h3 className={home.whatHead}>What is this?</h3>
                        <p className={home.thaiSpread}>
                            Thai Sign Language is the primary language for the hearing impaired to communicate in Thailand. However, 
                            Thai society still lacks easily accessible and quality tools for learning and interpreting sign language systematically. 
                            This project aims to develop a platform that uses technology to help reduce the communication gap and increase learning opportunities for everyone in society. 
                            It is supported by funding from NSTDA and has received sign language data from the Thai Deaf Association.
                        </p>
                        <br/>
                        <h4>Powered by</h4>
                        <ul className={home.tech_list}>
                            <li>
                                <img src="https://www.rapiddg.com/sites/default/files/imce-files/react.png"/>
                                React
                            </li>
                            <li>
                                <img src="https://viz.mediapipe.dev/logo.png"/>
                                Mediapipe
                            </li>
                            <li>
                                <img src="https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Heart_coraz%C3%B3n.svg/800px-Heart_coraz%C3%B3n.svg.png"/>
                                And Love
                            </li>
                        </ul>
                    </div>
                </div>
            </section>
            <br></br>
            <section className={`${home.section} ${home.aboutSec}`}>
                <div className={`${home.container} ${home.grid_2}`}>
                    <div className={home.text}>
                        <h3 className={home.whatHead}>About us</h3>
                        <p className={home.thaiSpread}>
                            We are a group of students from Nongbua Pittayakarn School who have developed this web application to provide a convenient and accessible tool for those interested in learning Thai Sign Language. 
                            It uses motion detection technology through video cameras to translate sign language into text in real-time.
                        </p>
                        <br/>
                        <h4>Participants</h4>
                        <ul className={home.tech_list}>
                            <li>
                                <img src="https://www.rapiddg.com/sites/default/files/imce-files/react.png"/>
                                Dontarit Haisok
                            </li>
                            <li>
                                <img src="https://www.rapiddg.com/sites/default/files/imce-files/react.png"/>
                                Chindanai Chaipim
                            </li>
                            <li>
                                <img src="https://www.rapiddg.com/sites/default/files/imce-files/react.png"/>
                                Tanawit Phadasri
                            </li>
                        </ul>
                    </div>
                    <img className={home.image} src="https://placehold.co/500x500" alt="Profile"/>
                </div>
            </section>
        </div>
        <section id="content" className={`${home.section} ${home.dark}`}>
            <div className={home.container}>
                <h3 className={home.section_title}>Why choose us?</h3>
                <div id="project_grid" className={home.grid_3}></div>
            </div>
        </section>
        <section id="together" className={home.section}>
            <div className={home.container}>
                <h3 className={home.section_title}>
                    <p>Let's learn</p>
                    <p className={home.accent}>Thai Sign Language</p>
                </h3>
                <a href="#home" className={`${home.btn} ${home.small}`}>I'm ready</a>
            </div>
        </section>
        <footer>
            <div className={home.container}>
                <p>© <span id="year"></span> | Crafted with <i className="ph-fill ph-heart"></i> by Dontarit</p>
            </div>
        </footer>
        <div id="overlay-setting-container"></div>
        </>
    )
}
